import currency
__game = Hash(default_value=0, contract='con_survival', name='game')
__operator = Variable(contract='con_survival', name='operator')
random.seed()


def ____(vk: str):
    __operator.set(vk)
    __game['boss_enabled'] = False
    __game['amount_boss'] = 1500
    __game['character_number'] = 4
    __game['last_redeem'] = now
    __game['play_cost'] = 20
    __game['redeem_time'] = 1
    __game['fail_attack'] = 5
    __game['chance_instakill'] = 3
    __game['chance_life'] = 18
    __game['max_life_bar'] = 10
    __game['amount_steal_tau'] = decimal('0.20')
    __game['items_life'] = [20, 35, 90]
    __game['charge_life'] = [1, 2, 5]
    __game['items_weapon'] = [40, 90, 120]
    __game['stat_weapon'] = [2, 5, 8]
    __game['items_shield'] = [100]
    __game['stat_shield'] = [1]
    __game['items_skill'] = [40, 90, 120]
    __game['stat_skill'] = [2, 5, 8]
    __game['items_times'] = 5


@__export('con_survival')
def attack_survivor():
    caller = ctx.caller
    play_cost = __game['play_cost']
    assert currency.balance_of(caller
        ) >= play_cost, 'Not enough Balance to play!'
    currency.transfer_from(play_cost, __operator.get(), caller)
    __game[caller, 'zombie'] += 1
    GAMEID = __game['gameId']
    SURVIVOR = __game[GAMEID, 'survivor']
    __game[GAMEID, 'zombies_attack'] += 1
    SHIELD_ITEM = __game[SURVIVOR, 'item_shield']
    WEAPON_ITEM = __game[SURVIVOR, 'item_weapon']
    SKILL_ZOMBIE = __game[caller, 'item_skill']
    if SHIELD_ITEM is None:
        SHIELD_ITEM = 0
    if WEAPON_ITEM is None:
        WEAPON_ITEM = 0
    if SKILL_ZOMBIE is None:
        SKILL_ZOMBIE = 0
    __game[GAMEID, 'game_amount'] += 20
    randomFirstAttack = random.randint(1, 100)
    if __game[SURVIVOR, 'item_shield_times'] < 1:
        SHIELD_ITEM = 0
    else:
        __game[SURVIVOR, 'item_shield_times'] -= 1
    ATTACK_SHIELD = __shield()
    if (now - __game[GAMEID, SURVIVOR, 'have_sherif_shield_time']
        ).minutes > 90:
        ATTACK_SHIELD = False
        __game[GAMEID, SURVIVOR, 'have_sherif_shield'] = 0
    if randomFirstAttack <= __game['chance_instakill'] - SHIELD_ITEM:
        if ATTACK_SHIELD is True:
            __game[GAMEID, SURVIVOR, 'have_sherif_shield'] = 0
            return __kill_zombie(caller)
        else:
            __game[GAMEID, SURVIVOR, 'have_sherif_shield'] = 0
            return __kill_survivor(caller)
    else:
        randomSecondAttack = random.randint(1, 100)
        if __game[caller, 'item_skill_times'] < 1:
            SKILL_ZOMBIE = 0
        else:
            __game[caller, 'item_skill_times'] -= 1
        if __game[SURVIVOR, 'item_weapon_times'] < 1:
            WEAPON_ITEM = 0
        else:
            __game[SURVIVOR, 'item_weapon_times'] -= 1
        if randomFirstAttack <= __game['chance_life'
            ] + SKILL_ZOMBIE - WEAPON_ITEM:
            if __game[GAMEID, SURVIVOR, 'survivor_life'] < 1:
                return __kill_survivor(caller)
            else:
                return __attack_zombie(caller)
        else:
            return __kill_zombie(caller)


@__export('con_survival')
def redeem():
    caller = ctx.caller
    GAMEID = __game['gameId']
    SURVIVOR = __game[GAMEID, 'survivor']
    assert (now - __game[GAMEID, 'last_redeem']
        ).minutes >= 60, 'Not Cant redeem'
    if caller == SURVIVOR:
        AMOUNT = 50 * (now - __game[GAMEID, 'last_redeem']).hours
        if AMOUNT > 0:
            if __game[GAMEID, 'game_amount'] < AMOUNT:
                AMOUNT = __game[GAMEID, 'game_amount']
            currency.transfer_from(int(AMOUNT), SURVIVOR, __operator.get())
            __game[GAMEID, 'last_redeem'] = now
            __game[GAMEID, 'game_amount'] -= AMOUNT
            __game[GAMEID, 'game_survivor_gain'] += AMOUNT
            __game[caller, 'tau_gain'] += AMOUNT
            return {'gameId': GAMEID}


@__export('con_survival')
def change_value(variable: str, value: int):
    __assert_owner()
    __game[variable] = value


@__export('con_survival')
def change_value_array(variable: str, value: list):
    __assert_owner()
    __game[variable] = value


@__export('con_survival')
def start(account: str, amount: int):
    __assert_owner()
    __game['gameId'] = hashlib.sha3(str(now))
    GAMEID = __game['gameId']
    __game[GAMEID, 'survivor'] = account
    __game[GAMEID, 'last_redeem'] = now
    __game[GAMEID, 'game_amount'] = amount
    __game[GAMEID, 'survivor_date'] = now
    __game[account, 'survivor_time'] += 1
    EXTRA_BAR = __life_bar(account)
    __game[GAMEID, account, 'survivor_life'] = 5 + EXTRA_BAR
    __game[account, 'item_shield'] = 0
    __game[account, 'item_weapon'] = 0
    __game['avatar'] += 1
    __game[GAMEID, 'avatar'] += __game['avatar']
    if __game['avatar'] > __game['character_number']:
        __game['avatar'] = 1
        __game[GAMEID, 'avatar'] = 1
    __game[GAMEID, account, 'have_sherif_shield'] = 1
    __game[GAMEID, account, 'have_sherif_shield_time'] = now


def __life_bar(account: str):
    EXP = __game[account, 'zombies_kills']
    EXP_LIFE = EXP / 50
    EXP_LIFE = int(EXP_LIFE)
    if EXP_LIFE > 5:
        EXP_LIFE = 5
    __game[account, 'life_extra_bar'] = EXP_LIFE
    return EXP_LIFE


def __kill_zombie(account: str):
    GAMEID = __game['gameId']
    FAIL_AMOUNT = __game['fail_attack']
    SURVIVOR = __game[GAMEID, 'survivor']
    currency.transfer_from(FAIL_AMOUNT, SURVIVOR, __operator.get())
    __game[SURVIVOR, 'zombies_kills'] += 1
    __game[GAMEID, 'game_zombies_kills'] += 1
    __game[SURVIVOR, 'tau_gain'] += FAIL_AMOUNT
    __game[GAMEID, 'game_amount'] -= FAIL_AMOUNT
    __game[GAMEID, 'game_survivor_gain'] += FAIL_AMOUNT
    return {'survivor': SURVIVOR, 'status': 'fail_attack', 'amount': int(
        FAIL_AMOUNT), 'gameId': GAMEID}


def __attack_zombie(account: str):
    LAST_GAMEID = __game['gameId']
    SURVIVOR = __game[LAST_GAMEID, 'survivor']
    __game[LAST_GAMEID, SURVIVOR, 'survivor_life'] -= 1
    STEAL_AMOUNT = 50 * (now - __game[LAST_GAMEID, 'last_redeem']
        ).hours * __game['amount_steal_tau']
    if __game[LAST_GAMEID, 'game_amount'] <= STEAL_AMOUNT:
        STEAL_AMOUNT = __game[LAST_GAMEID, 'game_amount'] * __game[
            'amount_steal_tau']
    if STEAL_AMOUNT == 0:
        STEAL_AMOUNT = __game[LAST_GAMEID, 'game_amount'] * __game[
            'amount_steal_tau']
    __game[LAST_GAMEID, 'game_amount'] -= int(STEAL_AMOUNT)
    if STEAL_AMOUNT > 0:
        currency.transfer_from(int(STEAL_AMOUNT), account, __operator.get())
    else:
        STEAL_AMOUNT = 0
    __game[LAST_GAMEID, 'game_zombies_gain'] += int(STEAL_AMOUNT)
    __game[account, 'tau_zombie_gain'] += int(STEAL_AMOUNT)
    return {'survivor': SURVIVOR, 'status': 'steal_life', 'amount': int(
        STEAL_AMOUNT), 'gameId': LAST_GAMEID}


def __kill_survivor(account: str):
    LAST_GAMEID = __game['gameId']
    SURVIVOR = __game[LAST_GAMEID, 'survivor']
    STEAL_AMOUNT = 50 * (now - __game[LAST_GAMEID, 'last_redeem']).hours
    LAST_AMOUNT = __game[LAST_GAMEID, 'game_amount']
    if LAST_AMOUNT <= STEAL_AMOUNT:
        STEAL_AMOUNT = __game[LAST_GAMEID, 'game_amount'] * decimal('0.50')
    if STEAL_AMOUNT == 0:
        STEAL_AMOUNT = __game[LAST_GAMEID, 'game_amount'] * decimal('0.50')
    __game['gameId'] = hashlib.sha3(str(now))
    GAMEID = __game['gameId']
    __game[GAMEID, 'survivor'] = account
    __game[GAMEID, 'game_amount'] = int(LAST_AMOUNT - STEAL_AMOUNT)
    __game[GAMEID, 'last_redeem'] = now
    __game[account, 'survivor_time'] += 1
    __game[GAMEID, 'survivor_date'] = now
    __game[GAMEID, 'game_survivor_gain'] += STEAL_AMOUNT
    __game[account, 'tau_gain'] += STEAL_AMOUNT
    EXTRA_BAR = __life_bar(account)
    __game[GAMEID, account, 'survivor_life'] = 5 + EXTRA_BAR
    __game['avatar'] += 1
    __game[GAMEID, 'avatar'] = __game['avatar']
    if __game['avatar'] > __game['character_number']:
        __game['avatar'] = 1
        __game[GAMEID, 'avatar'] = 1
    __game[GAMEID, account, 'have_sherif_shield'] = 1
    __game[GAMEID, account, 'have_sherif_shield_time'] = now
    __game[account, 'item_shield'] = 0
    __game[account, 'item_weapon'] = 0
    if STEAL_AMOUNT > 0:
        currency.transfer_from(STEAL_AMOUNT, account, __operator.get())
    return {'survivor': account, 'status': 'new_survivor', 'avatar': __game
        ['avatar'], 'amount': int(STEAL_AMOUNT), 'lastId': LAST_GAMEID,
        'gameId': GAMEID}


def __shield():
    GAMEID = __game['gameId']
    SURVIVOR = __game[GAMEID, 'survivor']
    HAVE_SHIELD = __game[GAMEID, SURVIVOR, 'have_sherif_shield']
    if HAVE_SHIELD == 1:
        randomShield = random.randint(1, 100)
        if randomShield <= 80:
            return True
    else:
        return False


@__export('con_survival')
def weapon(item: int):
    caller = ctx.caller
    LIST_ITEM = __game['items_weapon']
    ITEM_STATS = __game['stat_weapon']
    currency.transfer_from(LIST_ITEM[item], __operator.get(), caller)
    __game[caller, 'item_weapon'] = ITEM_STATS[item]
    __game[caller, 'item_weapon_times'] = __game['items_times']


@__export('con_survival')
def shield_buy(item: int):
    caller = ctx.caller
    LIST_ITEM = __game['items_shield']
    ITEM_STATS = __game['stat_shield']
    currency.transfer_from(LIST_ITEM[item], __operator.get(), caller)
    __game[caller, 'item_shield'] = ITEM_STATS[item]
    __game[caller, 'item_shield_times'] = 1


@__export('con_survival')
def skill(item: int):
    caller = ctx.caller
    LIST_ITEM = __game['items_skill']
    ITEM_STATS = __game['stat_skill']
    currency.transfer_from(LIST_ITEM[item], __operator.get(), caller)
    __game[caller, 'item_skill'] = ITEM_STATS[item]
    __game[caller, 'item_skill_times'] = __game['items_times']


@__export('con_survival')
def life(item: int):
    caller = ctx.caller
    GAMEID = __game['gameId']
    LIST_ITEM = __game['items_life']
    CHARGE_LIFE = __game['charge_life']
    currency.transfer_from(LIST_ITEM[item], __operator.get(), caller)
    if __game[GAMEID, caller, 'survivor_life'] > 5 + __game[caller,
        'life_extra_bar']:
        __game[GAMEID, caller, 'survivor_life'] = 5 + __game[caller,
            'life_extra_bar']
    else:
        __game[GAMEID, caller, 'survivor_life'] += CHARGE_LIFE[item]


@__export('con_survival')
def attack_boss():
    caller = ctx.caller
    GAMEID = __game['gameId']
    SURVIVOR = __game[GAMEID, 'survivor']
    if caller == SURVIVOR:
        if __game['boss_enabled'] is True:
            randomBoss = random.randint(1, 4)
            if randomBoss == 4:
                __game[caller, 'boss_kill'] += 1
                __game[GAMEID, 'game_survivor_gain'] += __game['amount_boss']
                __game[caller, 'tau_gain'] += AMOUNT
                currency.transfer_from(__game['amount_boss'], caller,
                    __operator.get())
                return True
            else:
                return False
        else:
            return False
    else:
        return False


@__export('con_survival')
def set_nick_name(nickname: str):
    caller = ctx.caller
    assert len(nickname) <= 25, 'Nickname too long (25 chars max).'
    assert len(nickname) > 0, 'Nickname too short.'
    names_uid = hashlib.sha3(nickname.lower().replace(' ', ''))
    assert not __game['nicknames', names_uid
        ], 'A form of this name already belongs to ' + balances['nicknames',
        names_uid]
    __game[caller, 'nickname'] = nickname
    __game['nicknames', names_uid] = nickname


def __assert_owner():
    assert ctx.caller == __operator.get(), 'Only operator can call!'
